<script>
(function(window,document){
'use strict';
var API='api/work-settings.php';
var csrf=<?= json_encode($csrfToken, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
var state={settings:{},terms:[],users:[],can_update:false,visitOpen:false};
function E(id){return document.getElementById(id)}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}
function toast(t,m){if(typeof window.fieldplxToast==='function')window.fieldplxToast(t,m);else if(t==='error')window.alert(m)}
function icons(){if(window.lucide&&typeof window.lucide.createIcons==='function')window.lucide.createIcons()}
function fd(action){var f=new FormData();f.append('csrf_token',csrf);f.append('action',action);return f}
function request(data){return fetch(API,{method:'POST',body:data,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.text().then(function(txt){var d;try{d=JSON.parse(txt)}catch(e){throw new Error('Invalid response from work settings API.')}if(!r.ok||!d.success)throw new Error(d.message||'Request failed.');return d})})}
function checked(v){return Number(v||0)===1?' checked':''}
function selected(a,b){return String(a)===String(b)?' selected':''}
function termName(id){id=Number(id||0);for(var i=0;i<state.terms.length;i++){if(Number(state.terms[i].id)===id)return state.terms[i].term_name}return 'Select a term'}
function initials(u){var a=String(u.first_name||'').charAt(0),b=String(u.last_name||'').charAt(0);return (a+b).toUpperCase()||'U'}
function renderTermDropdown(kind,id){var title=kind==='residential'?'Default residential term':'Default commercial term';var icon=kind==='residential'?'circle-user-round':'building-2';var html='<div class="ws-select-card" data-select-card="'+kind+'"><i class="ico" data-lucide="'+icon+'"></i><div><small>'+title+'</small><strong data-term-label="'+kind+'">'+esc(termName(id))+'</strong></div><i class="chev" data-lucide="chevron-down"></i><div class="ws-dropdown">';state.terms.forEach(function(t){html+='<button type="button" data-term-pick="'+kind+'" data-id="'+Number(t.id)+'" class="'+(Number(id)===Number(t.id)?'selected':'')+'">'+esc(t.term_name)+'</button>'});html+='</div></div>';return html}
function renderTerms(){
    var html='<div class="ws-term-box"><div class="ws-term-list"><div class="ws-term-list-head"><div class="ws-term-cell">Term name</div><div class="ws-term-cell">Number of days</div><div class="ws-term-action-cell"></div></div>';
    state.terms.forEach(function(t){
        html+='<div class="ws-term-list-row"><div class="ws-term-cell">'+esc(t.term_name)+'</div><div class="ws-term-cell">'+(t.term_type==='days'?Number(t.number_days||0)+' days':'—')+'</div><div class="ws-term-action-cell">';
        if(Number(t.is_system||0)===1){
            html+='<span class="ws-icon-btn" title="Built-in payment term"><i data-lucide="lock-keyhole"></i></span>';
        }else{
            html+='<div class="ws-menu-wrap"><button type="button" class="ws-icon-btn" data-term-menu="'+Number(t.id)+'" aria-label="Payment term actions"><i data-lucide="ellipsis"></i></button><div class="ws-menu" data-menu-for="'+Number(t.id)+'"><button type="button" data-edit-term="'+Number(t.id)+'"><i data-lucide="pencil"></i>Edit</button><button type="button" class="danger" data-delete-term="'+Number(t.id)+'"><i data-lucide="trash-2"></i>Delete</button></div></div>';
        }
        html+='</div></div>';
    });
    html+='</div></div><button type="button" class="ws-add-link" id="addTermBtn"><i data-lucide="plus"></i>Add New</button>';
    return html;
}
function render(){var s=state.settings;var reminderUsers=Array.isArray(s.invoice_reminder_user_ids)?s.invoice_reminder_user_ids.map(Number):[];var arrival=String(s.arrival_window_minutes==null?'0':s.arrival_window_minutes);var vars=[['{{CLIENT_NAME}}',"Customer's Name"],['{{CLIENT_LAST_NAME}}',"Customer's Last Name"],['{{JOB_NUMBER}}','Job Number'],['{{JOB_TITLE}}','Job Title'],['{{STREET}}','Both Street Address Fields'],['{{STREET1}}',"Property's First Street Address Field"],['{{STREET2}}',"Property's Second Street Address Field"],['{{CITY}}',"Property's City"],['{{STATE_OR_PROVINCE}}',"Property's State or Province"],['{{POSTAL_CODE}}',"Property's Postal Code"],['{{PHONE_NUMBER}}',"Customer's Phone Number"]];var html='';
html+='<section class="ws-card"><div class="ws-card-inner"><h2>Quotes</h2><div class="ws-row top"><label class="ws-toggle"><input type="checkbox" id="quoteReminderEnabled"'+checked(s.quote_reminder_enabled)+'><span class="ws-toggle-ui"></span></label><div><div class="ws-label" style="margin-bottom:8px">Reminder</div><div class="ws-row" style="flex-wrap:wrap"><span class="ws-copy">Add a reminder to your calendar to check in on quotes that haven\'t been converted after</span><span class="ws-inline-input"><input id="quoteReminderDays" type="number" min="1" max="365" value="'+Number(s.quote_reminder_days||3)+'"><span>days</span></span></div></div></div></div></section>';
html+='<section class="ws-card"><div class="ws-card-inner"><h2>Jobs</h2><div class="ws-label">Default arrival window</div><div class="ws-pills" id="arrivalPills">';[['0','None'],['15','15 min'],['30','30 min'],['60','1 hr'],['120','2 hr'],['180','3 hr'],['240','4 hr']].forEach(function(x){html+='<button type="button" class="ws-pill'+(arrival===x[0]?' active':'')+'" data-arrival="'+x[0]+'">'+x[1]+'</button>'});html+='</div><div style="height:15px"></div><div class="ws-label">Arrival window style</div><div class="ws-radio-list"><label class="ws-radio"><input type="radio" name="arrival_style" value="after_start"'+(String(s.arrival_window_style||'after_start')==='after_start'?' checked':'')+'><i class="ws-radio-icon" data-lucide="calendar-range"></i><div><div class="ws-radio-title">Add window after start time</div><div class="ws-radio-example">ex. 9:00 AM – 10:00 AM</div></div></label><label class="ws-radio"><input type="radio" name="arrival_style" value="centered"'+(String(s.arrival_window_style)==='centered'?' checked':'')+'><i class="ws-radio-icon" data-lucide="calendar-clock"></i><div><div class="ws-radio-title">Center window on start time</div><div class="ws-radio-example">ex. 8:30 AM – 9:30 AM</div></div></label></div><div style="height:16px"></div><div class="ws-label">Visit titles</div><p class="ws-copy">Visit titles will display on your calendar and lists.</p><div id="visitWarning" class="ws-warning" style="display:none"><i data-lucide="triangle-alert"></i><span><strong>Warning:</strong> Changes will overwrite all future generated visit titles.</span></div><input class="ws-input" id="visitTitleTemplate" value="'+esc(s.visit_title_template||'{{CLIENT_NAME}} - {{JOB_TITLE}}')+'" style="margin-top:12px"><div class="ws-variable-wrap"><button type="button" class="ws-variable-toggle'+(state.visitOpen?' open':'')+'" id="visitVariableToggle">Custom visit title variables<i data-lucide="chevron-down"></i></button><div class="ws-variable-panel'+(state.visitOpen?' open':'')+'" id="visitVariablePanel"><p class="ws-copy" style="margin-bottom:8px">Customize your visit titles with the following available variables:</p><table class="ws-var-table"><thead><tr><th>Variable</th><th>Output</th></tr></thead><tbody>';vars.forEach(function(v){html+='<tr><td>'+esc(v[0])+'</td><td>'+esc(v[1])+'</td></tr>'});html+='</tbody></table></div></div></div></section>';
html+='<section class="ws-card"><div class="ws-card-inner"><h2>Invoices</h2><div class="ws-invoice-grid"><div><div class="ws-copy" style="padding-top:10px">Invoice subject</div></div><div class="ws-field-stack"><input class="ws-input" id="invoiceSubject" maxlength="190" value="'+esc(s.invoice_subject||'For Services Rendered')+'"><label class="ws-check"><input type="checkbox" id="useWorkTitle"'+checked(s.invoice_use_work_title)+'><span>Use quote or job title as invoice subject if available</span></label></div><div><div class="ws-copy">Payment terms</div><p class="ws-copy" style="margin-top:6px;font-style:italic">Set your typical payment terms for residential and commercial customers. These defaults can still be overridden by customer-specific settings.</p></div><div><div class="ws-term-selects">'+renderTermDropdown('residential',s.default_residential_term_id)+renderTermDropdown('commercial',s.default_commercial_term_id)+'</div>'+renderTerms()+'</div></div><div class="ws-section-separator"></div><div class="ws-label">Invoice reminders</div><p class="ws-copy">Set up scheduled reminders to invoice customers for recurring jobs.</p><label class="ws-check" style="margin-top:10px"><input type="checkbox" id="reassignIncomplete"'+checked(s.reassign_incomplete_invoice_reminders)+'><span>Reassign all incomplete invoice reminders</span></label><div class="ws-label" style="margin-top:14px;text-transform:uppercase;font-size:9px">Assigned to</div><div class="ws-assignee-list">';state.users.forEach(function(u){var uid=Number(u.id);html+='<label class="ws-assignee"><input type="checkbox" class="ws-reminder-user" value="'+uid+'"'+(reminderUsers.indexOf(uid)>=0?' checked':'')+'><span class="ws-assignee-avatar">'+esc(initials(u))+'</span><span class="ws-copy">'+esc(((u.first_name||'')+' '+(u.last_name||'')).trim()||u.email||'Team member')+'</span></label>'});if(!state.users.length)html+='<span class="ws-copy ws-muted">No active team members available.</span>';html+='</div></div></section>';
html+='<section class="ws-card"><div class="ws-card-inner"><h2>Statements</h2><div class="ws-grid-2"><div class="ws-copy">Sort order of billing history</div><select class="ws-select" id="statementSort"><option value="newest"'+selected(s.statement_sort_order,'newest')+'>Newest first</option><option value="oldest"'+selected(s.statement_sort_order,'oldest')+'>Oldest first</option></select><div><div class="ws-copy">Contract/disclaimer</div><p class="ws-copy" style="margin-top:5px;font-style:italic">This message will appear at the bottom of every statement</p></div><textarea class="ws-textarea" id="statementDisclaimer">'+esc(s.statement_disclaimer||'')+'</textarea></div></div></section>';
html+='<section class="ws-card"><div class="ws-card-inner"><h2 style="display:flex;align-items:center;flex-wrap:wrap">Chemical tracking <span class="ws-badge">Plan feature</span></h2><div class="ws-row"><label class="ws-toggle"><input type="checkbox" id="chemicalTracking"'+checked(s.chemical_tracking_enabled)+'><span class="ws-toggle-ui"></span></label><span class="ws-copy">Track chemical and pesticide usage</span></div><p class="ws-copy" style="margin-top:13px;font-style:italic">Chemical tracking will appear in your settings under Business Management when enabled for your plan.</p></div></section><div class="ws-save-row"><button type="button" class="ws-btn primary" id="saveSettingsBtn">Update Settings</button></div>';
E('workSettingsRoot').innerHTML=html;wire();icons()}
function wire(){document.querySelectorAll('[data-arrival]').forEach(function(b){b.onclick=function(){document.querySelectorAll('[data-arrival]').forEach(function(x){x.classList.remove('active')});b.classList.add('active')}});E('visitVariableToggle').onclick=function(){state.visitOpen=!state.visitOpen;this.classList.toggle('open',state.visitOpen);E('visitVariablePanel').classList.toggle('open',state.visitOpen);icons()};var original=String(state.settings.visit_title_template||'{{CLIENT_NAME}} - {{JOB_TITLE}}');E('visitTitleTemplate').addEventListener('input',function(){E('visitWarning').style.display=this.value!==original?'flex':'none'});document.querySelectorAll('[data-select-card]').forEach(function(card){card.onclick=function(e){if(e.target.closest('[data-term-pick]'))return;closeDropdowns(card);card.querySelector('.ws-dropdown').classList.toggle('open')}});document.querySelectorAll('[data-term-pick]').forEach(function(b){b.onclick=function(e){e.stopPropagation();var kind=b.getAttribute('data-term-pick'),id=Number(b.getAttribute('data-id'));if(kind==='residential')state.settings.default_residential_term_id=id;else state.settings.default_commercial_term_id=id;document.querySelector('[data-term-label="'+kind+'"]').textContent=termName(id);document.querySelectorAll('[data-term-pick="'+kind+'"]').forEach(function(x){x.classList.toggle('selected',Number(x.getAttribute('data-id'))===id)});closeDropdowns()}});document.querySelectorAll('[data-term-menu]').forEach(function(b){b.onclick=function(e){e.stopPropagation();var id=b.getAttribute('data-term-menu');closeMenus();var m=document.querySelector('[data-menu-for="'+id+'"]');if(m){m.classList.add('open');var r=b.getBoundingClientRect();var mw=148;var left=Math.min(window.innerWidth-mw-12,Math.max(12,r.right-mw));var mh=m.offsetHeight||92;var top=r.bottom+4;if(top+mh>window.innerHeight-12){top=Math.max(12,r.top-mh-4)}m.style.left=left+'px';m.style.top=top+'px'}}});document.querySelectorAll('[data-edit-term]').forEach(function(b){b.onclick=function(){openEditTerm(Number(b.getAttribute('data-edit-term')))}});document.querySelectorAll('[data-delete-term]').forEach(function(b){b.onclick=function(){openDeleteModal(Number(b.getAttribute('data-delete-term')))}});E('addTermBtn').onclick=openNewTerm;E('saveSettingsBtn').onclick=saveSettings}
function closeDropdowns(except){document.querySelectorAll('.ws-dropdown.open').forEach(function(d){if(!except||d.parentNode!==except)d.classList.remove('open')})}
function closeMenus(){document.querySelectorAll('.ws-menu.open').forEach(function(m){m.classList.remove('open');m.style.left='';m.style.top=''})}
document.addEventListener('click',function(e){if(!e.target.closest('.ws-select-card'))closeDropdowns();if(!e.target.closest('.ws-menu-wrap'))closeMenus()});
function load(){var f=fd('load');request(f).then(function(d){state.settings=d.settings||{};state.terms=d.terms||[];state.users=d.users||[];state.can_update=d.can_update!==false;render()}).catch(function(e){E('workSettingsRoot').innerHTML='<div class="ws-card"><div class="ws-loading">'+esc(e.message)+'</div></div>';toast('error',e.message)})}
function saveSettings(){var btn=E('saveSettingsBtn'),f=fd('save_settings'),active=document.querySelector('[data-arrival].active'),style=document.querySelector('input[name="arrival_style"]:checked'),users=[];document.querySelectorAll('.ws-reminder-user:checked').forEach(function(x){users.push(x.value)});f.append('quote_reminder_enabled',E('quoteReminderEnabled').checked?'1':'0');f.append('quote_reminder_days',E('quoteReminderDays').value);f.append('arrival_window_minutes',active?active.getAttribute('data-arrival'):'0');f.append('arrival_window_style',style?style.value:'after_start');f.append('visit_title_template',E('visitTitleTemplate').value);f.append('invoice_subject',E('invoiceSubject').value);f.append('invoice_use_work_title',E('useWorkTitle').checked?'1':'0');f.append('default_residential_term_id',String(state.settings.default_residential_term_id||0));f.append('default_commercial_term_id',String(state.settings.default_commercial_term_id||0));f.append('reassign_incomplete_invoice_reminders',E('reassignIncomplete').checked?'1':'0');users.forEach(function(id){f.append('invoice_reminder_user_ids[]',id)});f.append('statement_sort_order',E('statementSort').value);f.append('statement_disclaimer',E('statementDisclaimer').value);f.append('chemical_tracking_enabled',E('chemicalTracking').checked?'1':'0');btn.disabled=true;btn.textContent='Saving...';request(f).then(function(d){toast('success',d.message);return load()}).catch(function(e){toast('error',e.message)}).then(function(){btn.disabled=false;btn.textContent='Update Settings'})}
function openModal(){E('paymentTermModal').classList.add('open');E('paymentTermModal').setAttribute('aria-hidden','false');icons()}
function closeModal(){E('paymentTermModal').classList.remove('open');E('paymentTermModal').setAttribute('aria-hidden','true')}
function openNewTerm(){closeMenus();E('paymentTermForm').reset();E('termId').value='0';E('paymentTermTitle').textContent='Add new payment term';E('termWarning').style.display='none';openModal();setTimeout(function(){E('termName').focus()},30)}
function openEditTerm(id){closeMenus();for(var i=0;i<state.terms.length;i++){var t=state.terms[i];if(Number(t.id)===id){if(Number(t.is_system||0)===1)return;E('termId').value=String(id);E('termName').value=t.term_name||'';E('termDays').value=String(t.number_days==null?'':t.number_days);E('paymentTermTitle').textContent='Edit payment term';E('termWarning').style.display='flex';openModal();return}}}
function openDeleteModal(id){closeMenus();var term=null;for(var i=0;i<state.terms.length;i++){if(Number(state.terms[i].id)===id){term=state.terms[i];break}}if(!term||Number(term.is_system||0)===1)return;E('deleteTermId').value=String(id);E('deleteTermName').textContent=term.term_name||'this payment term';E('deletePaymentTermModal').classList.add('open');E('deletePaymentTermModal').setAttribute('aria-hidden','false');icons()}
function closeDeleteModal(){E('deletePaymentTermModal').classList.remove('open');E('deletePaymentTermModal').setAttribute('aria-hidden','true')}
function deleteTerm(id){var btn=E('confirmDeleteTermBtn'),f=fd('delete_term');f.append('term_id',String(id));btn.disabled=true;btn.textContent='Deleting...';request(f).then(function(d){toast('success',d.message);closeDeleteModal();load()}).catch(function(e){toast('error',e.message)}).then(function(){btn.disabled=false;btn.textContent='Delete'})}
E('closeTermModal').onclick=closeModal;E('cancelTermModal').onclick=closeModal;E('paymentTermModal').onclick=function(e){if(e.target===this)closeModal()};E('closeDeleteTermModal').onclick=closeDeleteModal;E('cancelDeleteTermModal').onclick=closeDeleteModal;E('deletePaymentTermModal').onclick=function(e){if(e.target===this)closeDeleteModal()};E('confirmDeleteTermBtn').onclick=function(){var id=Number(E('deleteTermId').value||0);if(id>0)deleteTerm(id)};document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeModal();closeDeleteModal();closeMenus()}});E('paymentTermForm').onsubmit=function(e){e.preventDefault();var f=new FormData(this),btn=E('saveTermBtn');btn.disabled=true;btn.textContent='Saving...';request(f).then(function(d){toast('success',d.message);closeModal();load()}).catch(function(err){toast('error',err.message)}).then(function(){btn.disabled=false;btn.textContent='Save'})};
load();icons();
})(window,document);
